{"code":"def transform(grid):
    # Mirror the pattern in both directions, then enlarge every cell to 2x2.
    rows = grid[::-1] + grid
    cols = []
    for row in rows:
        cols.append(row[::-1] + row)
    out = []
    for row in cols:
        for _ in range(2):
            expanded = []
            for x in row:
                expanded.extend([x, x])
            out.append(expanded)
    return out"}

